#pragma once
#include "kstationStartupTask.h"
#include "kstationStartupControlTask.h"
#include "kstationHdiWait.h"
#include <variant>
namespace kstation {
// Reset/runtime/Main startup owner. Named service children remain explicit;
// the outer board routes them to their independent native owners.
class NativeStartupControl final {
 using F=StartupTask;using C=StartupColdTask;using P=StartupPrefixTask;using R=StartupRuntimeTask;using M=StartupMainTask;
 struct Job{std::variant<F,C,P,R,M>task{F{F::Kind::ColdClear}};uint32_t child=0;};
public:
 struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,4>CodeRanges{{{0x142,0x1bc},{0x240,0x2ae},{0x2f4,0x2fe},{0x3a58,0x3ae4}}};
 bool active()const{return depth_!=0;}void reset(){depth_=0;steps_=0;}uint64_t steps()const{return steps_;}
 uint32_t requestedChild()const{return depth_&&waiting(jobs_[depth_-1])?jobs_[depth_-1].child:0;}
 static bool candidate(uint32_t pc){for(auto r:CodeRanges)if(pc>=r.begin&&pc<r.end)return true;return false;}
 bool step(Stage1Cpu&c){if(c.interruptMode2||c.pending_irqs_high||(c.pending_irqs&&!(c.ccr&128)))return false;auto at=uint32_t(c.getPC());if(!depth_||boundary(jobs_[depth_-1])!=at){Job j;if(at==0x142)j.task.emplace<F>(F::Kind::ColdClear);else if(at==0x280)j.task.emplace<F>(F::Kind::Pins);else if(at==0x2f4)j.task.emplace<F>(F::Kind::WaitStates);else if(at==0x3a58)j.task.emplace<F>(F::Kind::MainScratchClear);else if(at==0x15c)j.task.emplace<C>();else if(at==0x166)j.task.emplace<P>();else if(at==0x240)j.task.emplace<R>();else if(at==0x3a6c)j.task.emplace<M>();else return false;if(depth_==jobs_.size())throw std::logic_error("Native K startup child capacity");jobs_[depth_++]=j;}
  auto&j=jobs_[depth_-1];resume(j,c);if(at!=boundary(j))throw std::logic_error("Native K startup owner boundary differs");if(c.pending_irqs)c.read8(0xfffff2);auto len=bytes(j);auto cr=credits(j,c,len);auto cost=nextClocks(j,cr);auto begin=c.cycles;c.fetchClocks(len);c.pc=c.makepc(at+1);project(j,c);
  std::visit([&](auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,F>)t.advanceBefore(cost,cr.write,cr.ret,[&](F::Publication p){if(t.kind()==F::Kind::Pins||t.kind()==F::Kind::WaitStates)value(c,int8_t(p.value));if(p.width==2)c.write16(0,fieldAddress(p));else c.write8(int8_t(p.value),fieldAddress(p));if(t.kind()==F::Kind::ColdClear||t.kind()==F::Kind::MainScratchClear)value(c,0);});else if constexpr(std::is_same_v<T,C>||std::is_same_v<T,R>)t.advanceBefore(cost,cr);else if constexpr(std::is_same_v<T,P>)t.advanceBefore(cost,cr,[&]{c.reg8(8)=c.read8(0xfffe3d);value(c,c.reg8(8));return uint8_t(c.reg8(8));},[&](unsigned v){value(c,c.reg8(8));c.write8(int8_t(v),0xfffe3d);});else t.advanceBefore(cost,cr,[&](M::Read field)->unsigned{auto r=field==M::Read::Bank?9:1;c.reg8(r)=c.read8(field==M::Read::Bank?0xbb12:0xbb13);value(c,c.reg8(r));return uint8_t(c.reg8(r));},[&](M::Write field,unsigned v){if(field==M::Write::Tick){c.write16(int16_t(v),0xcd6a);value(c,c.reg16(6));}else{auto r=field==M::Write::Bank?9:1;value(c,c.reg8(r));c.write8(int8_t(v),field==M::Write::Bank?0xcd82:0xcd83);}});},j.task);
  if(c.cycles-begin!=cost)throw std::logic_error("Native K startup control clocks differ");bool complete=std::visit([](const auto&t){return t.complete();},j.task);if(complete){if(auto*f=std::get_if<F>(&j.task)){if(f->kind()==F::Kind::ColdClear)c.pc=c.makepc(0x15c);else if(f->kind()==F::Kind::MainScratchClear)c.pc=c.makepc(0x3a6c);}if(std::holds_alternative<M>(j.task))c.pc=c.makepc(0x3ae4);if(auto*p=std::get_if<P>(&j.task))c.pc=c.makepc(p->romCopy()?0x382:0x2fe);--depth_;}else if(!waiting(j))c.pc=c.makepc(boundary(j));++steps_;return true;
 }
private:
 static unsigned fieldAddress(F::Publication p){switch(p.field){case F::Field::P6Data:return 0xffffcb;case F::Field::P6Direction:return 0xffffc9;case F::Field::P8Data:return 0xffffcf;case F::Field::P8Direction:return 0xffffcd;case F::Field::P9Data:return 0xffffd2;case F::Field::P9Direction:return 0xffffd0;case F::Field::PAData:return 0xffffd3;case F::Field::PADirection:return 0xffffd1;case F::Field::PBData:return 0xffffd6;case F::Field::PBDirection:return 0xffffd4;case F::Field::P4Direction:return 0xffffc5;case F::Field::AccessState:return 0xffffed;case F::Field::WaitControl:return 0xffffee;case F::Field::InternalClear:return 0xfffd10+p.index*2;case F::Field::MainScratch:return 0xcd6c+p.index;}return 0;}
 static bool waiting(const Job&j){return std::visit([](const auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,F>)return false;else return t.awaiting();},j.task);}
 static void resume(Job&j,Stage1Cpu&c){std::visit([&](auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,M>){if(t.awaiting())t.resume(uint16_t(c.reg16(6)));}else if constexpr(!std::is_same_v<T,F>){if(t.awaiting())t.resume();}},j.task);}
 static unsigned nextClocks(const Job&j,const FlashCredits&c){return std::visit([&](const auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,F>)return t.nextClocks(c.write,c.ret);else return t.nextClocks(c);},j.task);}
 static unsigned boundary(const Job&j){return std::visit([](const auto&t)->unsigned{using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,F>){using S=F::Stage;if(t.kind()==F::Kind::Pins)return t.stage()==S::Return?0x2ac:0x280+t.index()*4+(t.stage()==S::Publish?2:0);if(t.kind()==F::Kind::WaitStates)return t.stage()==S::Return?0x2fc:0x2f4+t.index()*4+(t.stage()==S::Publish?2:0);if(t.kind()==F::Kind::ColdClear){switch(t.stage()){case S::BindTarget:return 0x142;case S::BindCount:return 0x148;case S::Publish:return 0x14e;case S::AdvanceTarget:return 0x150;case S::Decrement:return 0x152;case S::Repeat:return 0x154;case S::BindRuntimeStack:return 0x156;default:return 0;}}switch(t.stage()){case S::BindTarget:return 0x3a58;case S::BindCount:return 0x3a5e;case S::PrepareValue:return 0x3a62;case S::Publish:return 0x3a64;case S::AdvanceTarget:return 0x3a66;case S::Decrement:return 0x3a68;case S::Repeat:return 0x3a6a;default:return 0;}}
   else if constexpr(std::is_same_v<T,C>){static constexpr unsigned a[]={0x15c,0x15e,0x162,0};return a[unsigned(t.stage())];}
   else if constexpr(std::is_same_v<T,P>){static constexpr unsigned a[]={0x166,0x16a,0x16e,0x172,0x174,0x178,0x17a,0x17e,0x180,0x182,0x184,0x186,0x188,0x18a,0x18e,0x192,0x196,0x19a,0x19c,0x1a2,0x1a6,0x1ac,0x1ae,0x1b2,0x1b4,0x1b8,0};return a[unsigned(t.stage())];}
   else if constexpr(std::is_same_v<T,R>){static constexpr unsigned a[]={0x240,0x244,0x248,0x24c,0x250,0x254,0x258,0x25c,0x260,0x262,0x266,0x26a,0x26e,0x272,0x276,0x27a,0x27e,0};return a[unsigned(t.stage())];}
   else{static constexpr unsigned a[]={0x3a6c,0x3a70,0x3a74,0x3a78,0x3a7c,0x3a80,0x3a84,0x3a88,0x3a8c,0x3a90,0x3a94,0x3a96,0x3a9a,0x3a9c,0x3a9e,0x3aa2,0x3aa8,0x3aac,0x3ab0,0x3ab6,0x3abe,0x3ac6,0x3acc,0x3ad2,0x3ad6,0x3ada,0x3ade,0};return a[unsigned(t.stage())];}},j.task);}
 static unsigned bytes(const Job&j){if(auto*f=std::get_if<F>(&j.task)){using S=F::Stage;auto s=f->stage();return s==S::BindTarget||s==S::BindRuntimeStack||s==S::BindCount&&f->kind()==F::Kind::ColdClear?6:s==S::BindCount?4:2;}auto at=boundary(j);if(at==0x15c)return 2;if(auto*c=std::get_if<C>(&j.task))return 4;if(auto*p=std::get_if<P>(&j.task)){using S=P::Stage;auto s=p->stage();if(s==S::PublishMarker||s==S::ReadMarker)return 6;return s==S::RetainDelay||s==S::RetainInner||s==S::TickDelay||s==S::RepeatDelay||s==S::ReleaseInner||s==S::TickSettling||s==S::RepeatSettling||s==S::ReleaseDelay||s==S::ClearMarker||s==S::Compare55||s==S::CompareAA?2:4;}if(auto*r=std::get_if<R>(&j.task))return r->stage()==R::Stage::Unmask||r->stage()==R::Stage::Return?2:4;if(auto*m=std::get_if<M>(&j.task)){using S=M::Stage;auto s=m->stage();if(s==S::BindBackup||s==S::BindSelection||s==S::PublishBank||s==S::PublishProgram||s==S::PublishTick)return 6;if(s==S::ReadBank||s==S::ReadProgram)return 8;return s==S::BindAdc||s==S::ScaleAdc||s==S::RetainAdc?2:4;}return 2;}
 static unsigned bus(uint32_t at,unsigned n,int last){unsigned cost=0;for(unsigned i=0;i<n;++i){auto a=(at+i)&0xffffff;if(a<0x400000||(a>=0xfffd10&&a<0xffffa0)){if((last&1)||a!=uint32_t(last|1))cost+=a<0x400000?3:1;last=int(a);}else{cost+=a>=0xffffa0?1:3;last=-1;}}return cost;}
 static FlashCredits credits(const Job&j,const Stage1Cpu&c,unsigned len){FlashCredits cr;auto last=int(c.getPC()+len-1);cr.call=8+bus(c.getSP()-4,4,c.writeHistory());cr.shortCall=3+bus(c.getSP()-4,4,c.writeHistory());cr.ret=5+bus(c.getSP(),4,last);cr.pushWord=5+bus(c.getSP()-2,2,c.writeHistory());cr.popWord=5+bus(c.getSP(),2,last);if(auto*f=std::get_if<F>(&j.task)){if(f->stage()==F::Stage::Publish){auto p=f->publication();cr.write=bus(fieldAddress(p),p.width,c.writeHistory());}}else if(auto*p=std::get_if<P>(&j.task)){if(p->stage()==P::Stage::ReadMarker)cr.read=bus(0xfffe3d,1,last);if(p->stage()==P::Stage::PublishMarker)cr.write=bus(0xfffe3d,1,c.writeHistory());}else if(auto*m=std::get_if<M>(&j.task)){using S=M::Stage;switch(m->stage()){case S::ReadBank:cr.read=bus(0xbb12,1,last);break;case S::ReadProgram:cr.read=bus(0xbb13,1,last);break;case S::PublishBank:cr.write=bus(0xcd82,1,c.writeHistory());break;case S::PublishProgram:cr.write=bus(0xcd83,1,c.writeHistory());break;case S::PublishTick:cr.write=bus(0xcd6a,2,c.writeHistory());break;default:break;}}return cr;}
 static void value(Stage1Cpu&c,int v){c.ccr=uint8_t((c.ccr&~14)|(v<0?8:0)|(!v?4:0));}static void dec(Stage1Cpu&c,unsigned r){int old=c.reg16(r),v=old-1;value(c,v);if((old&~v)&0x8000)c.ccr|=2;c.reg16(r)=int16_t(v);}static void push(Stage1Cpu&c){c.setSP(c.getSP()-2);c.write16(c.reg16(0),int(c.getSP()));c.clockI(2);value(c,c.reg16(0));}static void pop(Stage1Cpu&c){c.reg16(0)=int16_t(c.read16(int(c.getSP())));c.setSP(c.getSP()+2);c.clockI(2);value(c,c.reg16(0));}
 static void ret(Stage1Cpu&c){auto sp=c.getSP();c.setSP(sp+4);c.clockI(2);c.pc=c.makepc(c.read32(int(sp))&0xffffff);c.irqDepth(c.irqDepth()-1);}
 static void dispatch(Job&j,Stage1Cpu&c,unsigned target,unsigned returned,bool wide=true){j.child=target;c.write32(returned,int(c.getSP()-4));c.setSP(c.getSP()-4);c.irqDepth(c.irqDepth()+1);if(wide)c.clockI(2);c.pc=c.makepc(target);}
 static void project(Job&j,Stage1Cpu&c){if(auto*f=std::get_if<F>(&j.task)){using S=F::Stage;auto k=f->kind();switch(f->stage()){case S::BindTarget:if(k==F::Kind::ColdClear){c.setSP(0xfffd10);value(c,c.getSP());}else{c.reg32(0)=0xcd6c;value(c,c.reg32(0));}break;case S::BindCount:if(k==F::Kind::ColdClear){c.reg32(0)=256;value(c,256);}else{c.reg16(9)=22;value(c,22);}break;case S::PrepareValue:c.reg8(k==F::Kind::MainScratchClear?9:8)=int8_t(f->publication().value);value(c,int8_t(f->publication().value));break;case S::AdvanceTarget:if(k==F::Kind::ColdClear)c.setSP(c.getSP()+2);else{++c.reg32(0);value(c,c.reg32(0));}break;case S::Decrement:dec(c,k==F::Kind::ColdClear?0:9);break;case S::BindRuntimeStack:c.setSP(0xffff10);value(c,c.getSP());break;case S::Return:ret(c);break;default:break;}}
  else if(auto*t=std::get_if<C>(&j.task)){switch(t->stage()){case C::Stage::Prefix:dispatch(j,c,0x166,0x15e,false);break;case C::Stage::Runtime:dispatch(j,c,0x240,0x162);break;case C::Stage::Main:c.clockI(2);c.pc=c.makepc(0x3a58);break;default:break;}}
  else if(auto*t=std::get_if<P>(&j.task)){using S=P::Stage;switch(t->stage()){case S::Pins:dispatch(j,c,0x280,0x16a);break;case S::WaitStates:dispatch(j,c,0x2f4,0x16e);break;case S::PanelReset:dispatch(j,c,0x2104,0x172);break;case S::RetainDelay:case S::RetainInner:push(c);break;case S::CountSettling:c.reg16(0)=10;value(c,10);break;case S::CountDelay:c.reg16(0)=2663;value(c,2663);break;case S::TickDelay:case S::TickSettling:dec(c,0);break;case S::ReleaseInner:case S::ReleaseDelay:pop(c);break;case S::LcdInitialize:dispatch(j,c,0x232e,0x18e);break;case S::InterruptSetup:dispatch(j,c,0x830,0x192);break;case S::TimerSetup:dispatch(j,c,0x846,0x196);break;case S::BoundsCheck:dispatch(j,c,0x1434,0x19a);break;case S::ClearMarker:c.reg8(8)=0;value(c,0);break;case S::BootProbe:dispatch(j,c,0xf46,0x1a6);break;case S::Compare55:arithmetic(c,uint8_t(c.reg8(8)),0x55);break;case S::CompareAA:arithmetic(c,uint8_t(c.reg8(8)),0xaa);break;case S::Select55:case S::SelectAA:case S::VerifyImage:c.clockI(2);break;default:break;}}
  else if(auto*t=std::get_if<R>(&j.task)){using S=R::Stage;unsigned target=0,returned=unsigned(c.getPC())+3;switch(t->stage()){case S::LcdInitialize:case S::LcdAgain:target=0x232e;break;case S::KeyboardInitialize:target=0x44c;break;case S::SerialSetup:target=0x9b6;break;case S::SerialEnable:target=0x9d0;break;case S::EncoderInitialize:target=0x1bc6;break;case S::PanelQueues:target=0x1ea4;break;case S::InterruptSetup:target=0x830;break;case S::TimerSetup:target=0x846;break;case S::Unmask:c.ccr&=0x3f;break;case S::AdcStart:target=0x54a;break;case S::DspBootstrap:target=0x14ee;break;case S::DspGlobals:target=0x5b38;break;case S::DelayTables:target=0x17ba;break;case S::StartupBanner:target=0x1456;break;case S::LcdCharacters:target=0x23c2;break;case S::Return:ret(c);break;default:break;}if(target)dispatch(j,c,target,returned);}
  else if(auto*t=std::get_if<M>(&j.task)){using S=M::Stage;unsigned target=0,returned=unsigned(c.getPC())+3;switch(t->stage()){case S::Metadata:target=0x5aa0;break;case S::Scheduler1:target=0x388c;break;case S::Scheduler2:target=0x38e8;break;case S::Scheduler3:target=0x3944;break;case S::Scheduler4:target=0x39a0;break;case S::Scheduler5:target=0x39fc;break;case S::ClearUi:target=0x4b5c;break;case S::ArpInitialize:target=0x3402;break;case S::MidiInitialize:target=0x251a;break;case S::ClockInitialize:target=0x4444;break;case S::BindAdc:c.reg8(14)=0x18;value(c,0x18);break;case S::ReadAdc:target=0x5cc;break;case S::ScaleAdc:{auto v=uint8_t(c.reg8(14));c.ccr=uint8_t((c.ccr&~1)|(v&1));c.reg8(14)=int8_t(v>>1);value(c,c.reg8(14));break;}case S::RetainAdc:c.reg8(6)=c.reg8(14);value(c,c.reg8(6));break;case S::ApplyAdc:target=0x403c;break;case S::BindBackup:c.reg32(6)=0x21fe00;value(c,c.reg32(6));break;case S::BackupGlobals:target=0x55a4;break;case S::LoadGlobals:target=0x5556;break;case S::BindSelection:c.reg32(0)=0xba5c;value(c,c.reg32(0));break;case S::LoadProgram:target=0x4ca0;break;case S::UpdateDisplay:target=0x4358;break;case S::ReadTick:target=0x9aa;break;default:break;}if(target)dispatch(j,c,target,returned);}
 }
 static void arithmetic(Stage1Cpu&c,unsigned a,unsigned b){unsigned r=(a-b)&255;c.ccr=uint8_t((c.ccr&~0x2f)|(!r?4:0)|((r&128)?8:0)|((((~a&b)|(~a&r)|(b&r))&128)?1:0)|((((~a&b)|(~a&r)|(b&r))&8)?32:0)|((((a&~b&~r)|(~a&b&r))&128)?2:0));}
 std::array<Job,8>jobs_{};unsigned depth_=0;uint64_t steps_=0;
};
}
